const $ = s => document.querySelector(s);
const escapeHTML = s => String(s).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='little-ai-library-v1';let state={page:0,done:[],saved:[],notes:{},dark:false,size:0};
try{const v=JSON.parse(localStorage.getItem(KEY));if(v&&typeof v==='object'){state={...state,...v};state.page=Number.isInteger(v.page)&&v.page>=0&&v.page<lessons.length?v.page:0;for(const k of ['done','saved'])state[k]=Array.isArray(v[k])?[...new Set(v[k].filter(n=>Number.isInteger(n)&&n>=0&&n<lessons.length))]:[];state.notes=v.notes&&typeof v.notes==='object'?v.notes:{};state.size=[0,1,2].includes(v.size)?v.size:0;}}catch{}
let selected=null,busy=false,practiceIndex=0,toastTimer;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('Browser storage is unavailable. Progress lasts for this session.')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function para(s){return s.split('|').map(p=>`<p>${p}</p>`).join('')}
function applyPreferences(){document.body.classList.toggle('dark',!!state.dark);document.documentElement.style.setProperty('--body-size',[15,17,19][state.size]+'px');$('#theme').textContent=state.dark?'☀':'☾'}
function render(){selected=null;const l=lessons[state.page],c=chapters[l.ch];$('#breadcrumb').textContent=`CHAPTER ${c.icon} / ${c.short.toUpperCase()}`;$('#chapter-title').textContent=c.title;$('#lesson-position').textContent=`LESSON ${state.page%4+1} OF 4  ·  READ + PRACTICE`;
$('#chapters').innerHTML=chapters.map((x,i)=>`<button class="chapter-btn ${i===l.ch?'selected':''}" data-chapter="${i}" ${i===l.ch?'aria-current="true"':''}><span class="chapter-num">${x.icon}</span><span>${x.short}<small>${x.desc}</small></span>${state.done.filter(n=>lessons[n].ch===i).length===4?'<span class="chapter-check">✓</span>':''}</button>`).join('');
$('#chapter-count').textContent='07';$('#percent').textContent=Math.round(state.done.length/lessons.length*100)+'%';$('#progress').style.width=state.done.length/lessons.length*100+'%';$('#progress-label').textContent=`${state.done.length} of ${lessons.length} lessons practiced`;
$('#left').innerHTML=`<div class="page-kicker"><span>✧</span> ${state.page%4===0?'A NEW CHAPTER':'ONE LITTLE IDEA AT A TIME'}</div><h2>${l.title}</h2><p class="lede">${l.subtitle}</p>${l.scene?'<div class="pixel-scene"><canvas id="scene" width="240" height="95" role="img" aria-label="Pixel art: a friendly computer, books, and a growing plant"></canvas><span class="scene-caption">a big world of ideas, one little page at a time</span></div>':''}${para(l.body)}<div class="concept"><div class="concept-label">✦ THE LITTLE TAKEAWAY</div><p>${l.takeaway}</p></div><div class="folio"><span>LITTLE AI LIBRARY</span><span>${String(state.page*2+1).padStart(2,'0')}</span></div>`;
$('#right').innerHTML=`<div class="page-kicker">LET’S MAKE IT CLICK <span class="tag">${l.code?'FILL THE GAP':'TRY IT YOURSELF'}</span></div><h3 style="margin-top:0">${l.rightTitle}</h3>${para(l.right)}<div class="example"><span class="example-label">A LITTLE EXAMPLE</span><p>${l.example}</p></div>${l.lab?labMarkup(l.lab):''}<div class="exercise"><div class="exercise-header"><span>✦ QUICK CHECK</span><span>${state.done.includes(state.page)?'✓ PRACTICED':'YOUR TURN'}</span></div><h3>${l.q}</h3>${l.options?l.options.map((o,i)=>`<button class="option" data-option="${i}" aria-pressed="false"><span>${'ABC'[i]}</span><span>${o}</span></button>`).join(''):`<div class="code-line">${escapeHTML(l.code).replace('___','<input id="answer" aria-label="Missing answer" autocomplete="off" spellcheck="false" placeholder="your answer">')}</div>`}<button class="check-btn" id="check">Check my answer <span>↗</span></button><p class="feedback" id="feedback" role="status" aria-live="polite"></p></div><div class="folio"><span>GROW AT YOUR OWN PACE</span><span>${String(state.page*2+2).padStart(2,'0')}</span></div>`;
$('#bookmark').textContent=state.saved.includes(state.page)?'♥ Page saved':'♡ Save page';$('#bookmark').classList.toggle('saved',state.saved.includes(state.page));$('#bookmark').setAttribute('aria-pressed',state.saved.includes(state.page));$('#prev').disabled=state.page===0;$('#next').innerHTML=state.page===lessons.length-1?'Finish & reflect ✧':'Turn the page <span>→</span>';$('#page-dots').innerHTML=Array.from({length:4},(_,i)=>`<button class="${i===state.page%4?'current':''}" data-page="${l.ch*4+i}" aria-label="Go to lesson ${i+1}" ${i===state.page%4?'aria-current="page"':''}></button>`).join('');
if(l.scene)drawScene();if(l.lab)updateLab(l.lab);persist();}
function navigate(n){if(busy||n<0||n>=lessons.length||n===state.page)return;busy=true;const book=$('#book');book.classList.toggle('backwards',n<state.page);book.classList.add('flipping');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const turnMs=parseFloat(getComputedStyle(book).getPropertyValue('--page-turn-duration'))||1200;setTimeout(()=>{state.page=n;render()},reduced?0:turnMs/2);setTimeout(()=>{book.classList.remove('flipping','backwards');busy=false;if(innerWidth<560)$('#chapter-title').scrollIntoView({block:'start',behavior:reduced?'instant':'smooth'})},reduced?10:turnMs+30)}
function check(){const l=lessons[state.page];let ok;if(l.options){if(selected===null){toast('Choose an answer first.');return}ok=selected===l.answer;document.querySelectorAll('.option').forEach((b,i)=>{b.classList.remove('correct','incorrect');if(i===selected)b.classList.add(ok?'correct':'incorrect')})}else{const input=$('#answer');if(!input.value.trim()){input.focus();toast('Fill in the missing piece first.');return}const normalize=x=>String(x).trim().replace(/\s+/g,'').toLowerCase();ok=normalize(input.value)===normalize(l.answer)||(!Number.isNaN(Number(l.answer))&&Number(input.value)===Number(l.answer));}
$('#feedback').className='feedback '+(ok?'good':'bad');$('#feedback').textContent=ok?'You got it! '+l.why:'Not quite — '+l.why+' Try again.';
if(ok&&!state.done.includes(state.page)){state.done.push(state.page);persist();$('#percent').textContent=Math.round(state.done.length/lessons.length*100)+'%';$('#progress').style.width=state.done.length/lessons.length*100+'%';$('#progress-label').textContent=`${state.done.length} of ${lessons.length} lessons practiced`;$('.exercise-header span:last-child').textContent='✓ PRACTICED';$('#pet-message').innerHTML='Look at you growing.<br>One idea at a time. ♡';if(state.done.length===lessons.length)toast('All 28 lessons practiced. Your next adventure: build something!');}}
function labMarkup(type){return type==='gradient'?'<div class="lab"><label for="slider">Learning rate α <output id="slider-value"></output></label><input id="slider" type="range" min="0.05" max="1.2" step="0.05" value="0.1"><div id="lab-result" aria-live="polite"></div></div>':'<div class="lab"><label for="slider">Decision threshold <output id="slider-value"></output></label><input id="slider" type="range" min="0" max="1" step="0.05" value="0.5"><div id="lab-result" aria-live="polite"></div></div>'}
function updateLab(type){const v=Number($('#slider').value);$('#slider-value').textContent=v.toFixed(2);$('#lab-result').textContent=type==='gradient'?`Starting w = 0 → new w = ${(6*v).toFixed(2)}. Loss: 9 → ${((6*v-3)**2).toFixed(2)}.`:`For p = 0.65, the decision is ${0.65+1e-9>=v?'POSITIVE':'NEGATIVE'}. Move the threshold to change the decision.`}
function openDialog(title,html){$('#dialog-title').textContent=title;$('#dialog-content').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
function practice(){const [q,a]=interviewPrompts[practiceIndex];openDialog('The interview nook',`<span class="tag">PROMPT ${practiceIndex+1} OF ${interviewPrompts.length}</span><h3>${q}</h3><p>Try explaining your answer out loud, then make a few notes. Focus on assumptions, tradeoffs, and evidence.</p><textarea class="notes" id="practice-notes" aria-label="Your interview notes" placeholder="Here’s how I would think about it…">${escapeHTML(state.notes[practiceIndex]||'')}</textarea><p class="interview-note">Notes save automatically in this browser. This is self-guided practice, not automated grading.</p><details><summary>Reveal the answer guide</summary><p>${a}</p></details><button class="check-btn" id="next-prompt">Next interview prompt →</button>`)}
function drawPet(ctx,x,y,s=1){const pixels=['      gg      ','     gGgg     ','      GG      ','   ppPPpppp   ','  pPPPPPPPPp  ',' pPPPPPPPPPPp ',' pPPkPPPPkPPp ',' pPPkPPPPkPPp ',' pPrrPPPPrrPp ','  pPPpPPpPPp  ','   ppPPPPpp   ','    pppppp    '];const colors={g:'#73925d',G:'#9bb87a',p:'#806291',P:'#cab2df',k:'#493653',r:'#df9ea8'};pixels.forEach((row,iy)=>[...row].forEach((v,ix)=>{if(colors[v]){ctx.fillStyle=colors[v];ctx.fillRect(x+ix*s,y+iy*s,s,s)}}))}
function drawScene(){const c=$('#scene').getContext('2d');c.imageSmoothingEnabled=false;c.fillStyle='#ded2ee';c.fillRect(32,70,177,3);c.fillStyle='#9b81b5';c.fillRect(47,25,56,36);c.fillStyle='#7a628d';c.fillRect(44,28,62,29);c.fillStyle='#d7e4c8';c.fillRect(49,29,52,26);c.fillStyle='#637850';c.fillRect(61,38,4,5);c.fillRect(85,38,4,5);c.fillRect(69,47,14,2);c.fillRect(67,45,2,2);c.fillRect(83,45,2,2);c.fillStyle='#9276aa';c.fillRect(69,61,11,6);c.fillRect(61,67,27,3);c.fillStyle='#d8b4a7';c.fillRect(116,64,39,6);c.fillStyle='#a9b890';c.fillRect(121,56,30,7);c.fillStyle='#bca1d1';c.fillRect(118,49,35,6);drawPet(c,161,46,2);c.fillStyle='#b9a1d1';[[35,24],[119,22],[205,33]].forEach(([x,y])=>{c.fillRect(x,y,2,8);c.fillRect(x-3,y+3,8,2)})}
$('#chapters').addEventListener('click',e=>{const b=e.target.closest('[data-chapter]');if(b)navigate(Number(b.dataset.chapter)*4)});$('#page-dots').addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b)navigate(Number(b.dataset.page))});
$('#right').addEventListener('click',e=>{const b=e.target.closest('[data-option]');if(b){selected=Number(b.dataset.option);document.querySelectorAll('.option').forEach((o,i)=>{o.classList.toggle('chosen',i===selected);o.classList.remove('correct','incorrect');o.setAttribute('aria-pressed',i===selected)});$('#feedback').textContent=''}if(e.target.closest('#check'))check()});$('#right').addEventListener('input',e=>{if(e.target.id==='slider')updateLab(lessons[state.page].lab)});$('#right').addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='answer')check()});
$('#prev').onclick=()=>navigate(state.page-1);$('#next').onclick=()=>state.page===lessons.length-1?openDialog('Your next adventure',`<p>You’ve reached the end of the book. You have practiced ${state.done.length} of ${lessons.length} lesson checks. Revisit any unfinished lessons, then build the projects on the last page.</p><button class="check-btn" id="review-unfinished">${state.done.length===lessons.length?'Practice interview questions':'Review an unfinished lesson'}</button>`):navigate(state.page+1);
$('#bookmark').onclick=()=>{const i=state.saved.indexOf(state.page);if(i<0)state.saved.push(state.page);else state.saved.splice(i,1);persist();$('#bookmark').textContent=i<0?'♥ Page saved':'♡ Save page';$('#bookmark').classList.toggle('saved',i<0);$('#bookmark').setAttribute('aria-pressed',i<0);toast(i<0?'A little bookmark for later.':'Bookmark removed.')};
$('#saved').onclick=()=>openDialog('Your saved pages',state.saved.length?state.saved.map(n=>`<button class="dialog-link" data-goto="${n}">${escapeHTML(lessons[n].title)} <span>↗</span></button>`).join(''):'<p>No bookmarks yet. Choose “Save page” on any lesson to keep it here.</p>');
$('#theme').onclick=()=>{state.dark=!state.dark;applyPreferences();persist()};$('#font').onclick=()=>{state.size=(state.size+1)%3;applyPreferences();persist();toast(['Standard','Larger','Largest'][state.size]+' reading text')};$('#practice-tab').onclick=practice;$('#read-tab').onclick=()=>{$('#dialog').close();$('#book').scrollIntoView({block:'start',behavior:'smooth'})};$('.brand').onclick=e=>{e.preventDefault();navigate(0)};
$('#close-dialog').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#dialog').close()}const b=e.target.closest('[data-goto]');if(b){$('#dialog').close();navigate(Number(b.dataset.goto))}if(e.target.id==='next-prompt'){practiceIndex=(practiceIndex+1)%interviewPrompts.length;practice()}if(e.target.id==='review-unfinished'){const i=lessons.findIndex((_,n)=>!state.done.includes(n));if(i<0)practice();else{$('#dialog').close();navigate(i)}}});$('#dialog').addEventListener('input',e=>{if(e.target.id==='practice-notes'){state.notes[practiceIndex]=e.target.value;persist()}});
function resources(){openDialog('Keep your curiosity going',`<p>This original introductory book is a starting point for study and interview preparation. For a course, use your syllabus to identify topics that need deeper treatment. For interviews, add hands-on coding and projects.</p><a class="dialog-link" href="https://developers.google.com/machine-learning/crash-course" target="_blank" rel="noopener">Google’s Machine Learning Crash Course ↗</a><a class="dialog-link" href="https://scikit-learn.org/stable/common_pitfalls.html" target="_blank" rel="noopener">scikit-learn: data leakage and common pitfalls ↗</a><a class="dialog-link" href="https://www.deeplearningbook.org/" target="_blank" rel="noopener">Deep Learning — Goodfellow, Bengio & Courville ↗</a><h3>A gentle study rhythm</h3><p>Read a lesson, close the book, explain the idea in your own words, and solve a new example. Revisit it after a day and again a week later. Pair each chapter with a small coding exercise.</p><p><strong>Your data:</strong> progress, saved pages, and notes stay in this browser’s local storage. They do not sync between devices. Clearing browser data removes them.</p>`)}$('#resources').onclick=resources;
$('.desk-heading').onclick=()=>{if(innerWidth<=850)openDialog('Choose your chapter',chapters.map((c,i)=>`<button class="dialog-link" data-goto="${i*4}">${c.icon} · ${c.title}</button>`).join(''))};
document.addEventListener('keydown',e=>{if($('#dialog').open||/INPUT|TEXTAREA|SELECT|BUTTON/.test(e.target.tagName)||e.altKey||e.ctrlKey||e.metaKey)return;if(e.key==='ArrowRight'){e.preventDefault();navigate(state.page+1)}if(e.key==='ArrowLeft'){e.preventDefault();navigate(state.page-1)}});
applyPreferences();drawPet($('#pet').getContext('2d'),0,3,2);render();
